INSERT INTO agent_step_record (incident_id, investigation_id, run_no, step_no, status, started_at, created_at,
                               updated_at)
SELECT #{s.incidentId}, #{s.investigationId}, #{s.runNo}, COALESCE(MAX(step_no), 0) + 1, 'RUNNING',
       #{s.startedAt}, #{s.startedAt}, #{s.startedAt}
FROM agent_step_record
WHERE investigation_id = #{s.investigationId}

mapper.select:
SELECT incident_id
FROM agent_step_record
WHERE id = #{id}
